<?php
if(!defined("FPDUAL_ENTRY")) {http_response_code(404);exit;}
function tutor_groups(array $d,string $cid):array { $a=(($_SESSION['role']??'')==='admin'||!empty($_SESSION['admin_tutor_mode']))?['grants'=>$d['admin_tutor_grants']??[]]:($d['accounts'][$_SESSION['account']??'']??[]);return array_intersect_key($d['courses'][$cid]['groups']??[],array_fill_keys($a['grants'][$cid]??[],true)); }
function tutor_scope(array $d,string $cid,string $gid):void {if(!in_array($_SESSION['role']??'',['tutor','admin'],true)||!isset(tutor_groups($d,$cid)[$gid]))fail('Grupo no autorizado',403);}
function tutor_company_scope(array $d,string $cid,string $eid):void { $l=participation($d,$cid,$eid);tutor_scope($d,$cid,$l['group']); }
function panel_url(string $v,string $cid='',string $p='',string $g=''):string{return 'index.php?'.http_build_query(array_filter(['v'=>$v,'c'=>$cid,'p'=>$p,'g'=>$g],fn($x)=>$x!==''));}
function panel_nav(string $role,string $view,string $cid):void {
 $p=(string)($_GET['p']??'home');$g=(string)($_GET['g']??'');global $d;
 $items=match($role){'admin'=>['GESTIÓN'=>['dashboard'=>['◈','Cuadro de mando'],'directory'=>['▤','Empresas'],'interests'=>['✓','Solicitudes de interés'],'first_contacts'=>['☎','Primer contacto'],'mail_preparer'=>['✉','Preparar correo'],'agenda'=>['◷','Agenda'],'campaigns'=>['✉','Campañas'],'inbox'=>['▣','Buzón empresarial'],'students'=>['▣','Alumnado'],'teacher'=>['♙','Mis grupos'],'documents'=>['▧','Expedientes']], 'ADMINISTRACIÓN'=>['courses'=>['▦','Cursos y grupos'],'teachers'=>['♙','Tutores docentes'],'registrations'=>['✓','Registros'],'settings'=>['⚙','Configuración']]],'company'=>['PORTAL EMPRESARIAL'=>['home'=>['◈','Resumen'],'profile'=>['▤','Mi empresa'],'students'=>['♙','Alumnado en prácticas'],'docs'=>['▧','Documentación'],'follow'=>['◷','Seguimiento']], 'GESTIÓN'=>['offers'=>['▦','Mis colaboraciones'],'sites'=>['⌖','Centros de trabajo'],'tutors'=>['♙','Tutores de empresa'],'account'=>['⚙','Mi cuenta']]],'tutor'=>['MI GRUPO'=>['home'=>['◈','Cuadro de mando'],'companies'=>['▤','Empresas y plazas'],'students'=>['▣','Alumnado'],'agenda'=>['◷','Seguimiento'],'docs'=>['▧','Documentación'],'account'=>['⚙','Mi cuenta']]],default=>[]};
 echo '<aside class="sidebar"><a class="sidebrand" href="'.h(panel_url(match($role){'admin'=>'dashboard','company'=>'portal',default=>'teacher'},$cid)).'"><span class="side-section">Menú principal</span></a><div class="side-role">'.h(match($role){'admin'=>'Administración del centro','company'=>'Portal de empresas',default=>'Tutor docente'}).'</div><nav aria-label="Menú principal">';foreach($items as $section=>$entries){echo '<div class="navlabel">'.h($section).'</div>';foreach($entries as $key=>[$ic,$label]){$selected=$role==='admin'?($view===$key||($key==='directory'&&in_array($view,['company','import']))):$p===$key;$url=$role==='admin'?panel_url($key,$cid):panel_url($role==='company'?'portal':'teacher',$cid,$key,$g);echo '<a '.($selected?'class="selected" aria-current="page" ':'').'href="'.h($url).'"><span class="navicon">'.h($ic).'</span>'.h($label).'</a>';}}if($role==='admin'&&$view==='teacher'){echo '<div class="navlabel">MIS GRUPOS</div>';foreach(['home'=>'Resumen docente','companies'=>'Empresas y plazas','students'=>'Alumnado de mi grupo','agenda'=>'Seguimiento','docs'=>'Documentación'] as $key=>$label){$url=panel_url('teacher',$cid,$key,$g);echo '<a '.($p===$key?'class="selected" ':'').'href="'.h($url).'">'.h($label).'</a>';}}echo '</nav><div class="sidebottom"><a href="index.php?v=landing">↗ Landing pública</a>';echo '</div></aside>';
}
function panel_metric(string $label,$v,string $note=''):void{echo '<div class="metric card"><small>'.h($label).'</small><strong>'.h($v).'</strong><span class="muted">'.h($note).'</span></div>';}
function panel_course_switch(array $opts,string $cid,string $view,string $p=''):void{echo '<form class="switcher" method="get"><input type="hidden" name="v" value="'.h($view).'"><input type="hidden" name="p" value="'.h($p).'"><label>Curso académico<select name="c">';foreach($opts as $k=>$label)echo '<option value="'.h($k).'"'.($k===$cid?' selected':'').'>'.h($label).'</option>';echo '</select></label><button class="secondary">Cambiar</button></form>';}
function teacher_admin(array $d,string $cid,array $gs,bool $ed):void{
 echo '<section class="card"><h2>Equipo docente · '.h($d['courses'][$cid]['name']).'</h2><p class="muted">Cada docente solo puede consultar y gestionar sus grupos asignados. Los permisos se establecen por curso académico.</p>';
 global $cfg;echo '<div class="record-card"><h3>Administrador · tutor docente</h3><p>'.h($d['admin_tutor_name']??$d['settings']['tutor']??'Administrador').' · '.h($cfg['admin_email']??'').'</p><p>La asignación docente no altera los permisos de administración ni requiere otra cuenta.</p>';if($ed){form_start('teacher_admin_grant',['c'=>$cid]);input('name','Nombre y apellidos',$d['admin_tutor_name']??$d['settings']['tutor']??'');foreach($gs as $gid=>$n)echo '<label class="check"><input type="checkbox" name="groups[]" value="'.h($gid).'"'.(in_array($gid,$d['admin_tutor_grants'][$cid]??[],true)?' checked':'').'>'.h($n).'</label>';end_form('Guardar mis grupos');}else foreach($d['admin_tutor_grants'][$cid]??[] as $gid)echo '<p>'.h($gs[$gid]??$gid).'</p>';echo '<a class="button secondary" href="'.h(panel_url('teacher',$cid)).'">Abrir mis grupos</a></div>'; $selected=(string)($_GET['record']??'');$base='?v=teachers&c='.rawurlencode($cid);if($selected!=='')echo '<a class="button secondary" href="'.h($base).'">← Volver al equipo docente</a>';foreach($d['accounts'] as $aid=>$acc){if(($acc['role']??'company')!=='tutor')continue;if($selected===''){echo '<div class="record-toolbar"><strong>'.h($acc['name'].' · '.$acc['email']).'</strong><a class="button secondary" href="'.h($base.'&record='.rawurlencode((string)$aid)).'">Abrir ficha</a></div>';continue;}if((string)$aid!==$selected)continue;echo '<div class="record-card"><h2>'.h($acc['name'].' · '.$acc['email']).'</h2>';if($ed){form_start('teacher_grant',['c'=>$cid,'aid'=>$aid]);foreach($gs as $gid=>$n)echo '<label class="check"><input type="checkbox" name="groups[]" value="'.h($gid).'"'.(in_array($gid,$acc['grants'][$cid]??[],true)?' checked':'').'>'.h($n).'</label>';end_form('Guardar permisos del curso');}else foreach($acc['grants'][$cid]??[] as $gid)echo '<p>'.h($gs[$gid]??$gid).'</p>';form_start('teacher_revoke',['c'=>$cid,'aid'=>$aid]);end_form('Revocar cuenta completa');echo '</div>';}
 foreach($d['invites'] as $k=>$inv){if(($inv['role']??'')!=='tutor'||$inv['expires']<time())continue;echo '<p class="notice">Invitación pendiente: '.h($inv['email']).'</p>';form_start('teacher_cancel',['c'=>$cid,'key'=>$k]);end_form('Cancelar invitación');}echo '</section>';if($ed&&$gs){echo '<section class="card"><h2>Invitar a un tutor docente</h2>';form_start('teacher_invite',['c'=>$cid]);input('name','Nombre y apellidos','','text',true);input('email','Correo profesional','','email',true);foreach($gs as $gid=>$n)echo '<label class="check"><input type="checkbox" name="groups[]" value="'.h($gid).'">'.h($n).'</label>';end_form('Enviar invitación con Resend');echo '</section>';}
 if(isset($_SESSION['teacher_invite'])){echo '<section class="card"><h2>Enlace privado de activación</h2><p>Compártalo exclusivamente con el docente autorizado. Caduca en siete días.</p><textarea readonly>'.h($_SESSION['teacher_invite']).'</textarea></section>';unset($_SESSION['teacher_invite']);}
}
function teacher_selected_groups(array $d,string $cid):array{$raw=$_POST['groups']??[];if(!is_array($raw))fail('Grupos inválidos');$out=[];foreach($raw as $g){if(!is_string($g)||!isset($d['courses'][$cid]['groups'][$g]))fail('Grupo inválido');$out[]=$g;}return array_values(array_unique($out));}

function panel_company_course(array $d,string $cid,string $master):bool{
 if(!isset($d['courses'][$cid]))return false;
 if(!empty($d['company_course_history'][$master][$cid]))return true;
 foreach($d['students'][$cid]??[] as $st)if(!empty($st['company'])&&master_id((string)$st['company'])===$master)return true;
 return false;
}
function panel_course_options(array $d,string $role,bool $teaching=false):array{
 $out=[];foreach($d['courses'] as $id=>$c){$id=(string)$id;if(($role==='admin'&&!$teaching)||(($role==='tutor'||($role==='admin'&&$teaching))&&tutor_groups($d,$id))||($role==='company'&&panel_company_course($d,$id,(string)($_SESSION['company']??''))))$out[$id]=$c['name'];}return $out;
}
function panel_top_course(array $d,string $role,string $view,string $cid):void{
 $opts=panel_course_options($d,$role,$role==='admin'&&$view==='teacher');$active=$d['settings']['active'];$activeName=$d['courses'][$active]['name']??'Sin configurar';echo '<div class="top-course"><span class="top-course-current">Vigente <strong>'.h($activeName).'</strong></span>';
 if($opts){$dest=$role==='company'?'portal':(($role==='tutor'||$view==='teacher')?'teacher':'dashboard');echo '<form method="get" class="top-course-form"><input type="hidden" name="v" value="'.h($dest).'"><label class="top-course-label"><select name="c" id="top-course-select" aria-label="Curso de trabajo">';if(!isset($opts[$cid]))echo '<option value="" selected disabled>Seleccione curso</option>';foreach($opts as $id=>$name)echo '<option value="'.h($id).'"'.($id===$cid?' selected':'').'>'.h($name).($id===$active?' · Vigente':' · Histórico').'</option>';echo '</select></label><button class="secondary top-course-go" type="submit" aria-label="Cambiar curso">Ir</button></form>';}else echo '<small>Sin cursos autorizados</small>';echo '</div>';
}

function admin_has_tutor_groups(array $d):bool{foreach($d['admin_tutor_grants']??[] as $cid=>$ids)foreach($ids as $gid)if(isset($d['courses'][$cid]['groups'][$gid]))return true;return false;}
function panel_role_switch(array $d,string $role):void{
 if(($role==='admin'&&admin_has_tutor_groups($d))||($role==='tutor'&&!empty($_SESSION['admin_tutor_mode']))){echo '<form method="post" class="top-role-form">'.post_hidden('switch_role').'<select name="target_role" id="top-role-select" aria-label="Rol de trabajo"><option value="admin"'.($role==='admin'?' selected':'').'>Administrador</option><option value="tutor"'.($role==='tutor'?' selected':'').'>Tutor docente</option></select><button class="secondary top-role-go" type="submit">Cambiar</button></form>';return;}
 echo '<span class="top-role">'.h(match($role){'admin'=>'Administrador','company'=>'Empresa colaboradora',default=>'Tutor docente'}).'</span>';
}
